#!/usr/bin/env cs_python
# Generated by air-translate --emit-csl-host
#
# Run against a pre-compiled artifact directory produced by
#   cslc layout.csl --arch=wseN ... -o <dir> --memcpy --channels 1
# The companion commands_wse{2,3}.sh scripts do both steps.

import argparse
import sys
import numpy as np

from cerebras.sdk.runtime.sdkruntimepybind import (
    SdkRuntime,
    MemcpyOrder,
    MemcpyDataType,
)

parser = argparse.ArgumentParser()
parser.add_argument('--name', default='compiled',
                    help='compiled artifact directory (default: compiled)')
parser.add_argument('--cmaddr', default=None,
                    help='IP:port for CS system (default: simulator)')
args = parser.parse_args()

N = 64

# Host buffers.
arg0 = np.arange(N, dtype=np.float32)
arg1 = np.arange(N, dtype=np.float32) * 2.0
arg2 = np.zeros(N, dtype=np.float32)

# Create runtime and load compiled artifacts.
runner = SdkRuntime(args.name, cmaddr=args.cmaddr, simfab_numthreads=32)
runner.load()
runner.run()

# Host-to-device copies (inputs).
runner.memcpy_h2d(runner.get_id("a"), arg0, 0, 0, 1, 1, 64,
                  streaming=False,
                  order=MemcpyOrder.ROW_MAJOR,
                  data_type=MemcpyDataType.MEMCPY_32BIT,
                  nonblock=False)
runner.memcpy_h2d(runner.get_id("b"), arg1, 0, 0, 1, 1, 64,
                  streaming=False,
                  order=MemcpyOrder.ROW_MAJOR,
                  data_type=MemcpyDataType.MEMCPY_32BIT,
                  nonblock=False)

# Launch compute kernel.
runner.launch("compute", nonblock=False)

# Device-to-host copies (outputs).
runner.memcpy_d2h(arg2, runner.get_id("c"), 0, 0, 1, 1, 64,
                  streaming=False,
                  order=MemcpyOrder.ROW_MAJOR,
                  data_type=MemcpyDataType.MEMCPY_32BIT,
                  nonblock=False)

runner.stop()

# Reference computation (numpy, interpreted from csl.func @compute body).
_a_ref = arg0[:64].astype(np.float32).copy()
_b_ref = arg1[:64].astype(np.float32).copy()
_c_ref = np.zeros(64, dtype=np.float32)
for i4 in range(0, 64, 1):
    t5 = _a_ref[i4]
    t6 = _b_ref[i4]
    t7 = i4 % 3
    if t7 == 0:
        t8 = t5 + t6
        _c_ref[i4] = t8
    elif t7 == 1:
        t9 = t5 - t6
        _c_ref[i4] = t9
    else:
        t10 = t5 * t6
        _c_ref[i4] = t10

# Verification: compare each D2H output against its reference.
_mismatch = False
_expected_arg2 = np.zeros_like(arg2)
_expected_arg2[:64] = _c_ref
if not np.allclose(arg2, _expected_arg2, atol=1e-5, rtol=1e-5):
    print("MISMATCH in arg2 (var @c):", file=sys.stderr)
    print(f"  expected[:8] = {_expected_arg2[:min(8, len(_expected_arg2))]}", file=sys.stderr)
    print(f"  got[:8]      = {arg2[:min(8, len(arg2))]}", file=sys.stderr)
    _mismatch = True
else:
    print(f"  arg2[:8] = {arg2[:min(8, len(arg2))]} (matches reference)")
if _mismatch:
    sys.exit(1)
print("SUCCESS!")
